import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, lineDiscount, lineVat, invoiceTotals, addLine, removeLine, issueInvoice } from '../src/invoices.js';

test('createInvoice returns a draft invoice with enriched lines', () => {
  const result = createInvoice({
    customerId: 'C-001', // Gold tier: 5% discount
    issueDate: '2025-01-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-001');
  assert.equal(result.value.issueDate, '2025-01-15');
  assert.equal(result.value.status, 'draft');
  assert.equal(result.value.lines.length, 2);

  // Check first line (gold tier 5% discount applied)
  assert.deepEqual(result.value.lines[0], {
    sku: 'DEV-HOUR',
    name: 'Development (hour)',
    qty: 5,
    unitPrice: 9500,
    vatRate: 21,
    discountPercent: 5,
  });

  // Check second line (gold tier 5% discount applied)
  assert.deepEqual(result.value.lines[1], {
    sku: 'LOGO-PACK',
    name: 'Logo package',
    qty: 1,
    unitPrice: 120000,
    vatRate: 21,
    discountPercent: 5,
  });
});

test('createInvoice fails with CUSTOMER_NOT_FOUND for unknown customer', () => {
  const result = createInvoice({
    customerId: 'C-999',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.equal(result.ok, false);
  assert.equal(result.error, 'CUSTOMER_NOT_FOUND');
});

test('createInvoice fails with DATE_INVALID for malformed dates', () => {
  const badDates = [
    '2025-1-15',
    '2025-01-5',
    '25-01-15',
    '2025/01/15',
    '01-15-2025',
    'invalid',
    '',
  ];

  for (const date of badDates) {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: date,
      lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    });
    assert.equal(result.ok, false, `date "${date}" should be invalid`);
    assert.equal(result.error, 'DATE_INVALID', `date "${date}" should fail with DATE_INVALID`);
  }
});

test('createInvoice fails with DATE_INVALID for impossible dates', () => {
  const impossibleDates = [
    '2025-02-30',
    '2025-04-31',
    '2025-13-01',
    '2025-00-15',
  ];

  for (const date of impossibleDates) {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: date,
      lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    });
    assert.equal(result.ok, false, `date "${date}" should be impossible`);
    assert.equal(result.error, 'DATE_INVALID', `date "${date}" should fail with DATE_INVALID`);
  }
});

test('createInvoice fails with NO_LINES for empty lines array', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [],
  });

  assert.equal(result.ok, false);
  assert.equal(result.error, 'NO_LINES');
});

test('createInvoice fails with NO_LINES for undefined lines', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: undefined,
  });

  assert.equal(result.ok, false);
  assert.equal(result.error, 'NO_LINES');
});

test('createInvoice fails with QTY_INVALID for invalid quantities', () => {
  const badQtys = [0, -1, -100, 1.5, NaN, Infinity];

  for (const qty of badQtys) {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-01-15',
      lines: [{ sku: 'DEV-HOUR', qty }],
    });
    assert.equal(result.ok, false, `qty ${qty} should be invalid`);
    assert.equal(result.error, 'QTY_INVALID', `qty ${qty} should fail with QTY_INVALID`);
  }
});

test('createInvoice fails with UNKNOWN_SKU for unknown SKU', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'UNKNOWN-SKU', qty: 1 }],
  });

  assert.equal(result.ok, false);
  assert.equal(result.error, 'UNKNOWN_SKU');
});

test('createInvoice fails on first error only', () => {
  // Test that it fails on customer first, before checking lines
  const result = createInvoice({
    customerId: 'C-999',
    issueDate: 'invalid',
    lines: [],
  });

  assert.equal(result.ok, false);
  assert.equal(result.error, 'CUSTOMER_NOT_FOUND');
});

test('createInvoice works with various SKUs and quantities', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-12-01',
    lines: [
      { sku: 'ICON-SET', qty: 2 },
      { sku: 'WORKSHOP-DAY', qty: 3 },
      { sku: 'PRINT-A4', qty: 100 },
    ],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines.length, 3);
  assert.equal(result.value.lines[0].qty, 2);
  assert.equal(result.value.lines[1].qty, 3);
  assert.equal(result.value.lines[2].qty, 100);
  assert.equal(result.value.lines[0].vatRate, 21);
  assert.equal(result.value.lines[1].vatRate, 0);
  assert.equal(result.value.lines[2].vatRate, 9);
});

test('lineTotal calculates qty times unitPrice', () => {
  assert.equal(lineTotal({ qty: 1, unitPrice: 9500 }), 9500);
  assert.equal(lineTotal({ qty: 5, unitPrice: 9500 }), 47500);
  assert.equal(lineTotal({ qty: 1, unitPrice: 120000 }), 120000);
  assert.equal(lineTotal({ qty: 100, unitPrice: 37 }), 3700);
});

test('lineTotal with qty 0 returns 0', () => {
  assert.equal(lineTotal({ qty: 0, unitPrice: 9500 }), 0);
});

test('invoiceTotals sums line totals', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 9500, vatRate: 21 },
      { qty: 1, unitPrice: 120000, vatRate: 21 },
    ],
  };

  const totals = invoiceTotals(invoice);
  const subtotal = 5 * 9500 + 1 * 120000; // 167500
  const vat = 9975 + 25200; // 21% of each = 35175
  assert.deepEqual(totals, {
    subtotal,
    discount: 0,
    vat,
    total: subtotal + vat,
  });
  assert.equal(totals.subtotal, 167500);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 35175);
  assert.equal(totals.total, 202675);
});

test('invoiceTotals with single line', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 6000, vatRate: 21 }],
  };

  const totals = invoiceTotals(invoice);
  const subtotal = 60000;
  const vat = 12600; // 21% of 60000
  assert.deepEqual(totals, { subtotal, discount: 0, vat, total: subtotal + vat });
});

test('invoiceTotals with multiple lines of different products', () => {
  const invoice = {
    lines: [
      { qty: 3, unitPrice: 8500, vatRate: 21 },
      { qty: 2, unitPrice: 980, vatRate: 21 },
      { qty: 100, unitPrice: 37, vatRate: 9 },
    ],
  };

  const subtotal = 3 * 8500 + 2 * 980 + 100 * 37; // 31160
  // VAT per line: 21% of 25500 = 5355, 21% of 1960 = 411.6 rounds to 412, 9% of 3700 = 333
  const vat = 5355 + 412 + 333; // 6100
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, subtotal);
  assert.equal(totals.vat, vat);
  assert.equal(totals.total, subtotal + vat);
});

test('invoiceTotals with empty lines', () => {
  const invoice = { lines: [] };
  const totals = invoiceTotals(invoice);
  assert.deepEqual(totals, { subtotal: 0, discount: 0, vat: 0, total: 0 });
});

test('invoiceTotals calculated from createInvoice result', () => {
  const result = createInvoice({
    customerId: 'C-001', // Gold tier: 5% discount, 21% VAT
    issueDate: '2025-01-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  });

  assert.equal(result.ok, true);
  const totals = invoiceTotals(result.value);
  const subtotal = 5 * 9500 + 1 * 120000; // 167500
  const discount = 8375; // 5% of 167500
  // VAT calculated per line: 21% of (47500 - 2375) + 21% of (120000 - 6000) = 21% of 45125 + 21% of 114000
  // = 9476.25 + 23940 = 33416.25, rounds to 33416
  const vat = 33416; // 21% of amount after discount per line
  assert.equal(totals.subtotal, subtotal);
  assert.equal(totals.discount, discount);
  assert.equal(totals.vat, vat);
  assert.equal(totals.total, subtotal - discount + vat);
});

test('addLine adds a new line to a draft invoice', () => {
  const result = createInvoice({
    customerId: 'C-001', // Gold tier: 5% discount
    issueDate: '2025-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert.equal(result.ok, true);
  const addResult = addLine(result.value, { sku: 'LOGO-PACK', qty: 2 });

  assert.equal(addResult.ok, true);
  assert.equal(addResult.value.lines.length, 2);
  assert.deepEqual(addResult.value.lines[0], {
    sku: 'DEV-HOUR',
    name: 'Development (hour)',
    qty: 5,
    unitPrice: 9500,
    vatRate: 21,
    discountPercent: 5,
  });
  assert.deepEqual(addResult.value.lines[1], {
    sku: 'LOGO-PACK',
    name: 'Logo package',
    qty: 2,
    unitPrice: 120000,
    vatRate: 21,
    discountPercent: 5,
  });
});

test('addLine increases qty if SKU already exists', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert.equal(result.ok, true);
  const addResult = addLine(result.value, { sku: 'DEV-HOUR', qty: 3 });

  assert.equal(addResult.ok, true);
  assert.equal(addResult.value.lines.length, 1);
  assert.equal(addResult.value.lines[0].sku, 'DEV-HOUR');
  assert.equal(addResult.value.lines[0].qty, 8);
});

test('addLine does not mutate the original invoice', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert.equal(result.ok, true);
  const original = result.value;
  addLine(original, { sku: 'LOGO-PACK', qty: 2 });

  assert.equal(original.lines.length, 1);
  assert.equal(original.lines[0].qty, 5);
});

test('addLine fails with QTY_INVALID for invalid quantities', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert.equal(result.ok, true);
  const badQtys = [0, -1, 1.5, NaN];

  for (const qty of badQtys) {
    const addResult = addLine(result.value, { sku: 'LOGO-PACK', qty });
    assert.equal(addResult.ok, false, `qty ${qty} should be invalid`);
    assert.equal(addResult.error, 'QTY_INVALID');
  }
});

test('addLine fails with UNKNOWN_SKU for unknown SKU', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert.equal(result.ok, true);
  const addResult = addLine(result.value, { sku: 'INVALID-SKU', qty: 1 });

  assert.equal(addResult.ok, false);
  assert.equal(addResult.error, 'UNKNOWN_SKU');
});

test('addLine fails with NOT_DRAFT if invoice status is not draft', () => {
  const invoiceData = {
    customerId: 'C-001',
    issueDate: '2025-01-15',
    status: 'sent',
    lines: [
      {
        sku: 'DEV-HOUR',
        name: 'Development (hour)',
        qty: 5,
        unitPrice: 9500,
        vatRate: 21,
      },
    ],
  };

  const addResult = addLine(invoiceData, { sku: 'LOGO-PACK', qty: 1 });

  assert.equal(addResult.ok, false);
  assert.equal(addResult.error, 'NOT_DRAFT');
});

test('removeLine removes a line from a draft invoice', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  });

  assert.equal(result.ok, true);
  const removeResult = removeLine(result.value, 'DEV-HOUR');

  assert.equal(removeResult.ok, true);
  assert.equal(removeResult.value.lines.length, 1);
  assert.equal(removeResult.value.lines[0].sku, 'LOGO-PACK');
});

test('removeLine does not mutate the original invoice', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  });

  assert.equal(result.ok, true);
  const original = result.value;
  removeLine(original, 'DEV-HOUR');

  assert.equal(original.lines.length, 2);
});

test('removeLine fails with LINE_NOT_FOUND for unknown SKU', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert.equal(result.ok, true);
  const removeResult = removeLine(result.value, 'UNKNOWN-SKU');

  assert.equal(removeResult.ok, false);
  assert.equal(removeResult.error, 'LINE_NOT_FOUND');
