  // Subtotal = 95 + 1200 = 1295
  // Discount = 4.75 + 120 = 124.75
  // Amount after discount = 1295 - 124.75 = 1170.25
  // VAT = 21% of 1170.25 = 245.7525, rounds to 24575 (banker's rounding)
  // Total = 1295 - 124.75 + 245.75 = 1415.25 => 141525
  assert.equal(totals.subtotal, 129500);
  assert.equal(totals.discount, 12475);
  assert.equal(totals.vat, 24575); // 245.7525 rounds to 245.75 per banker's rounding
  assert.equal(totals.total, 141600);
});

test('lineVat calculates VAT on amount after discount', () => {
  // 100.00 (unitPrice 10000, qty 1) with no discount, 21% VAT
  assert.equal(lineVat({ qty: 1, unitPrice: 10000, vatRate: 21 }), 2100);

  // 100.00 with 50% discount = 50.00, 21% VAT on 50.00 = 10.50
  assert.equal(lineVat({ qty: 1, unitPrice: 10000, discountPercent: 50, vatRate: 21 }), 1050);

  // 1000.00 with 10% discount = 900.00, 9% VAT on 900.00 = 81.00
  assert.equal(lineVat({ qty: 10, unitPrice: 10000, discountPercent: 10, vatRate: 9 }), 8100);
});

test('lineVat with 0% VAT rate returns 0', () => {
  assert.equal(lineVat({ qty: 1, unitPrice: 10000, vatRate: 0 }), 0);
  assert.equal(lineVat({ qty: 5, unitPrice: 10000, discountPercent: 10, vatRate: 0 }), 0);
});

test('lineVat never returns negative', () => {
  // Even with 100% discount
  assert.equal(lineVat({ qty: 1, unitPrice: 10000, discountPercent: 100, vatRate: 21 }), 0);
});

test('invoiceTotals returns VAT and recalculated total', () => {
  const invoice = {
    lines: [
      { qty: 1, unitPrice: 10000, vatRate: 21 }, // 100.00, no discount, 21% VAT = 21.00
      { qty: 1, unitPrice: 10000, vatRate: 9 },  // 100.00, no discount, 9% VAT = 9.00
    ],
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 20000); // 100 + 100
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 3000); // 21 + 9
  assert.equal(totals.total, 23000); // 200 + 30
});

test('invoiceTotals with discount and VAT', () => {
  const invoice = {
    lines: [
      { qty: 1, unitPrice: 10000, discountPercent: 10, vatRate: 21 }, // 100 - 10 = 90, VAT 21% of 90 = 18.90
      { qty: 1, unitPrice: 10000, discountPercent: 20, vatRate: 9 },  // 100 - 20 = 80, VAT 9% of 80 = 7.20
    ],
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 20000); // 100 + 100
  assert.equal(totals.discount, 3000); // 10 + 20
  assert.equal(totals.vat, 2610); // 1890 + 720
  assert.equal(totals.total, 19610); // 200 - 30 + 26.10
});

test('invoiceTotals with mixed VAT rates', () => {
  // DEV-HOUR: 95.00, 21% VAT
  // PRINT-A4: 0.37, 9% VAT
  // WORKSHOP-DAY: 600.00, 0% VAT
  const invoice = {
    lines: [
      { qty: 1, unitPrice: 9500, vatRate: 21 },
      { qty: 1, unitPrice: 37, vatRate: 9 },
      { qty: 1, unitPrice: 60000, vatRate: 0 },
    ],
  };

  const totals = invoiceTotals(invoice);
  const subtotal = 9500 + 37 + 60000; // 69537
  const vat1 = 1995; // 21% of 9500
  const vat2 = 3; // 9% of 37
  const vat3 = 0; // 0% of 60000
  const vat = vat1 + vat2 + vat3; // 1998

  assert.equal(totals.subtotal, subtotal);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, vat);
  assert.equal(totals.total, subtotal + vat);
});

test('invoiceTotals never returns negative total', () => {
  const invoice = {
    lines: [{ qty: 1, unitPrice: 1000, discountPercent: 100, vatRate: 21 }],
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 1000);
  assert.equal(totals.discount, 1000);
  assert.equal(totals.vat, 0); // 21% of 0 (after 100% discount)
  assert.equal(totals.total, 0); // 1000 - 1000 + 0
});

