  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 1 }, // Should get gold tier 5%
      { sku: 'LOGO-PACK', qty: 1, discountPercent: 15 }, // Explicit 15%
      { sku: 'COPY-HOUR', qty: 1, discountPercent: 0 }, // Explicit 0%
    ],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].discountPercent, 5); // Gold tier
  assert.equal(result.value.lines[1].discountPercent, 15); // Explicit
  assert.equal(result.value.lines[2].discountPercent, undefined); // Explicit 0
});

