test('VAT calculation example: services with discount', () => {
  // 5 hours of dev work at 95/hour = 475
  // With gold tier 5% discount = 451.25
  // 21% VAT on 451.25 = 94.7625, rounds to 9476
  // Total = 451.25 + 94.76 = 546.01 (in cents: 54601)

  // But we need to be precise with cents:
  // 5 * 9500 = 47500 cents
  // 47500 * 0.05 = 2375 discount
  // 47500 - 2375 = 45125 amount after discount
  // 45125 * 0.21 = 9476.25, rounds to 9476
  // Total = 47500 - 2375 + 9476 = 54601

  const result = createInvoice({
    customerId: 'C-001', // Gold tier 5%
    issueDate: '2025-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert.equal(result.ok, true);
  const totals = invoiceTotals(result.value);
  assert.equal(totals.subtotal, 47500);
  assert.equal(totals.discount, 2375);
  assert.equal(totals.vat, 9476);
  assert.equal(totals.total, 54601);
});

