test('createInvoice EOM handles different months', () => {
  const testCases = [
    { issueDate: '2025-02-15', expectedDueDate: '2025-02-28' },
    { issueDate: '2024-02-15', expectedDueDate: '2024-02-29' }, // leap year
    { issueDate: '2025-04-10', expectedDueDate: '2025-04-30' },
    { issueDate: '2025-12-25', expectedDueDate: '2025-12-31' },
  ];

  for (const tc of testCases) {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: tc.issueDate,
      lines: [{ sku: 'DEV-HOUR', qty: 1 }],
      terms: 'EOM',
    });

    assert.equal(result.ok, true, `EOM for ${tc.issueDate} should work`);
    assert.equal(result.value.dueDate, tc.expectedDueDate, `EOM for ${tc.issueDate}`);
  }
});

