test('applyVoucher adds voucher to draft invoice', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.equal(result.ok, true);
  const vouchResult = applyVoucher(result.value, { code: 'SAVE10', amount: 5000 });

  assert.equal(vouchResult.ok, true);
  assert.deepEqual(vouchResult.value.voucher, { code: 'SAVE10', amount: 5000 });
});

test('applyVoucher reduces total in invoiceTotals', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.equal(result.ok, true);
  const totalsWithoutVoucher = invoiceTotals(result.value);

  const vouchResult = applyVoucher(result.value, { code: 'SAVE10', amount: 5000 });
  assert.equal(vouchResult.ok, true);

  const totalsWithVoucher = invoiceTotals(vouchResult.value);

  assert.equal(totalsWithVoucher.voucher, 5000);
  assert.equal(totalsWithVoucher.total, totalsWithoutVoucher.total - 5000);
});

